 		for (tp = tcf_get_next_proto(chain, NULL, true);
 		     tp; tp = tcf_get_next_proto(chain, tp, true)) {
 			struct tcf_bind_args arg = {};

 			arg.w.fn = tcf_node_bind;
-			arg.classid = clid;
